#!/usr/bin/env node
// Synthetic Ego-compatible Page surface. Never accesses an account or live browser.
// Recovery mode replays the same snapshot; edits are tested in the separate stream mode.
(async()=>{const fs=require('fs');const {JSDOM}=await import('jsdom');const marker=process.env.BAMI_TEST_EGO_STATE;let attempt=0;if(marker){attempt=Number(fs.existsSync(marker)?fs.readFileSync(marker,'utf8'):'0')+1;fs.writeFileSync(marker,String(attempt));}if(attempt===1){const original=fs.createWriteStream;fs.createWriteStream=function(...args){const stream=original.apply(this,args),write=stream.write.bind(stream);stream.write=function(chunk,...rest){const value=JSON.parse(String(chunk));const result=write(chunk,...rest);if(value.kind==='row'&&value.row.id==='synthetic-image')setTimeout(()=>process.exit(21),150);return result};return stream};require('node:module').syncBuiltinESMExports();}const target='https://chatgpt.com/dots/00000000-0000-4000-8000-000000000001';const d=new JSDOM('<main><article data-message-id="synthetic-user" class="message-row self"><div class="message-surface">합성 한글 🌙</div></article><article data-message-id="synthetic-image" class="message-row"><div class="message-surface"><img alt="합성 이미지"></div></article></main><div contenteditable="true" role="textbox" aria-label="메시지"></div><button aria-label="보내기" disabled></button>',{url:target,runScripts:'outside-only'});const w=d.window;w.HTMLElement.prototype.getClientRects=()=>[{}];w.eval('HTMLElement.prototype.__defineGetter__("innerText",function(){return this.textContent;})');w.document.querySelector('.self .message-surface').textContent='한글 🌙'.repeat(25000);const img=w.document.querySelector('img');Object.defineProperties(img,{complete:{value:true},naturalWidth:{value:120},naturalHeight:{value:120}});w.HTMLCanvasElement.prototype.getContext=()=>({drawImage(){}});w.HTMLCanvasElement.prototype.toDataURL=()=> 'data:image/png;base64,'+fs.readFileSync('tests/fixtures/bami-image.png').toString('base64');let timer;const page={async goto(){if(!marker)timer=setTimeout(()=>{w.document.querySelector('.self .message-surface').textContent='수정된 합성 한글 🌙';},500)},async fill(_,text){w.document.querySelector('[contenteditable]').textContent=text;w.document.querySelector('button').disabled=!text},async click(){const a=w.document.createElement('article');a.className='message-row self';a.dataset.messageId='synthetic-preset-'+Date.now();const b=w.document.createElement('div');b.className='message-surface';b.textContent=w.document.querySelector('[contenteditable]').textContent;a.append(b);w.document.querySelector('main').append(a);w.document.querySelector('[contenteditable]').textContent=''},async waitForFunction(){},async url(){return w.location.href},async evaluate(fn,arg){w.__arg=arg;return w.eval('('+fn.toString()+')(__arg)')}};globalThis.taskSpace=async()=>({spaceId:1,ownership:'agent',page(){return page},async finish(){if(process.env.BAMI_TEST_EGO_FINISH)fs.writeFileSync(process.env.BAMI_TEST_EGO_FINISH,'finished');clearTimeout(timer);d.window.close()}});await eval('(async()=>{'+process.argv[4]+'})()');})().catch(()=>process.exit(1));
